
document.getElementById('year').textContent=new Date().getFullYear();document.querySelectorAll('.photo').forEach(p=>{function toggle(){p.classList.toggle('reveal');p.setAttribute('aria-pressed',p.classList.contains('reveal'))}p.addEventListener('click',toggle);p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})});

const soundButton=document.querySelector('.sound-toggle'),soundPanel=document.getElementById('sound-panel');function setSound(open){soundPanel.hidden=!open;soundButton.setAttribute('aria-expanded',String(open));if(open&&!document.querySelector('#spotify-slot iframe')){const frame=document.createElement('iframe');frame.src='https://open.spotify.com/embed/playlist/2zYjUGpmyMzr6wiqNI4olR?theme=0';frame.title='Spotify: Mellow Soul Jazz Instrumentals';frame.height='152';frame.allow='autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture';document.getElementById('spotify-slot').appendChild(frame)}if(!open)soundButton.focus()}soundButton.addEventListener('click',()=>setSound(soundPanel.hidden));document.querySelector('.sound-close').addEventListener('click',()=>setSound(false));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!soundPanel.hidden)setSound(false)});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.section-head,.service,.gallery figure,.pride-banner,.visit>div,.info article').forEach((el,i)=>{el.classList.add('reveal-ready');el.style.transitionDelay=(i%3)*65+'ms';observer.observe(el)})}

const legacyPages={'#services':'/services.html','#gallery':'/craft.html','#info':'/info.html'};if(legacyPages[location.hash])location.replace(legacyPages[location.hash]);
